import { Metadata } from 'next';
import { notFound } from 'next/navigation';
import BackButton from '../../../components/BackButton';

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  email: string;
  body: string;
}

type Params = Promise<{ id: string }>;

export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then((res) => res.json());

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  });

  if (!res.ok) return null;

  return res.json();
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
    next: { revalidate: 300 },
  });

  if (!res.ok) return [];

  return res.json();
}

export async function generateMetadata({
  params,
}: {
  params: Params;
}): Promise<Metadata> {
  const { id } = await params;
  const post = await getPost(id);

  if (!post) {
    return {
      title: 'Post Not Found',
    };
  }

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  };
}

export default async function BlogPost({
  params,
}: {
  params: Params;
}) {
  const { id } = await params;
  const postData = getPost(id);
  const commentsData = getComments(id);

  const [post, comments] = await Promise.all([postData, commentsData]);

  if (!post) {
    notFound();
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

